/* One entry of a StageModelCreate table (stage.c). size 0x38 (GC); no pointers. */
typedef struct StageModel_s {
    /* 0x00 */ u32 dataNum;      /* HU_DATANUM_NONE (-1) ends the table */
    /* 0x04 */ u32 attr;         /* Hu3DModelAttrSet */
    /* 0x08 */ s16 type;         /* STAGE_MODEL_TYPE_* */
    /* 0x0A */ s16 linkMdl;      /* TYPE_LINK: StageMdlId[] index to Hu3DModelLink */
    /* 0x0C */ s16 motMdl;       /* TYPE_MOT: StageMdlId[] index the motion is joined to */
    /* 0x0E */ s16 layer;        /* Hu3DModelLayerSet */
    /* 0x10 */ u16 cameraBit;    /* Hu3DModelCameraSet */
    /* 0x14 */ HuVecF pos;       /* SCREEN position, converted with Hu3D2Dto3D(.., HU3D_CAM1, ..) */
    /* 0x20 */ HuVecF rot;
    /* 0x2C */ HuVecF scale;
} STAGE_MODEL;

#define STAGE_MODEL_TYPE_MODEL 0
#define STAGE_MODEL_TYPE_MOT 1
#define STAGE_MODEL_TYPE_LINK 2

/* One entry of a StageSpriteCreate table (stage.c). size 0x14 (GC); dataNum 0 ends it. */
typedef struct StageSprite_s {
    /* 0x00 */ u32 dataNum;
    /* 0x04 */ s16 attr;
    /* 0x06 */ s16 prio;
    /* 0x08 */ float x;
    /* 0x0C */ float y;
    /* 0x10 */ GXColor color;    /* a = alpha 0..255 -> espTPLvlSet(a / 255.0f) */
} STAGE_SPRITE;

#define STAGE_MDL_MAX 128
#define STAGE_SPR_MAX 128

